      "keystrokes": "cat <<'CPP' > main.cpp\n#include <bits/stdc++.h>\nusing namespace std;\n\nint main(){\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    int n, m;\n    if(!(cin >> n >> m)) return 0;\n    vector<long long> w(n);\n    for(int i = 0; i < n; ++i) cin >> w[i];\n\n    vector<vector<pair<int,int>>> adj(n);\n    vector<pair<int,int>> edges(m);\n    for(int i = 0; i < m; ++i){\n        int u, v; cin >> u >> v; --u; --v;\n        edges[i] = {u, v};\n        adj[u].push_back({v, i});\n        adj[v].push_back({u, i});\n    }\n    int s; cin >> s; --s;\n\n    // Bridges via iterative DFS (Tarjan-like)\n    vector<int> tin(n, -1), low(n, 0), parent(n, -1), pedge(n, -1), iter(n, 0);\n    vector<char> isBridge(m, false);\n    int timer = 0;\n\n    for(int start = 0; start < n; ++start){\n        if(tin[start] != -1) continue;\n        vector<int> st;\n        st.push_back(start);\n        parent[start] = -1;\n        tin[start] = low[start] = ++timer;\n        iter[start] = 0;\n        while(!st.empty()){\n            int u = st.back();\n            if(iter[u] < (int)adj[u].size()){\n                auto [v, e] = adj[u][ iter[u]++ ];\n                if(tin[v] == -1){\n                    parent[v] = u;\n                    pedge[v] = e;\n                    tin[v] = low[v] = ++timer;\n                    iter[v] = 0;\n                    st.push_back(v);\n                } else if(v != parent[u]){\n                    low[u] = min(low[u], tin[v]);\n                }\n            } else {\n                st.pop_back();\n                if(parent[u] != -1){\n                    int p = parent[u];\n                    low[p] = min(low[p], low[u]);\n                    if(low[u] > tin[p]){\n                        isBridge[pedge[u]] = true;\n                    }\n                }\n            }\n        }\n    }\n\n    // Collapse into bridge components\n    vector<int> comp(n, -1);\n    int compCnt = 0;\n    for(int i = 0; i < n; ++i){\n        if(comp[i] != -1) continue;\n        stack<int> st;\n        st.push(i); comp[i] = compCnt;\n        while(!st.empty()){\n            int u = st.top(); st.pop();\n            for(auto [v, e] : adj[u]){\n                if(isBridge[e]) continue;\n                if(comp[v] == -1){\n                    comp[v] = compCnt;\n                    st.push(v);\n                }\n            }\n        }\n        compCnt++;\n    }\n\n    vector<long long> compW(compCnt, 0);\n    for(int i = 0; i < n; ++i) compW[comp[i]] += w[i];\n\n    // Build bridge-tree between components\n    vector<vector<int>> tadj(compCnt);\n    for(int i = 0; i < m; ++i){\n        if(!isBridge[i]) continue;\n        int u = edges[i].first, v = edges[i].second;\n        int cu = comp[u], cv = comp[v];\n        tadj[cu].push_back(cv);\n        tadj[cv].push_back(cu);\n    }\n\n    int root = comp[s];\n    // Iterative tree DP: get a spanning tree, then post-order\n    vector<int> par(compCnt, -2);\n    vector<char> vis(compCnt, false);\n    vector<int> order; order.reserve(compCnt);\n    vector<int> st; st.push_back(root); vis[root] = true; par[root] = -1;\n    while(!st.empty()){\n        int u = st.back(); st.pop_back();\n        order.push_back(u);\n        for(int v : tadj[u]){\n            if(!vis[v]){ vis[v] = true; par[v] = u; st.push_back(v); }\n        }\n    }\n\n    vector<long long> bestReturn(compCnt, 0), bestNoReturn(compCnt, 0);\n    for(int idx = (int)order.size() - 1; idx >= 0; --idx){\n        int u = order[idx];\n        long long sumReturn = 0;\n        for(int v : tadj[u]){\n            if(par[v] == u){\n                sumReturn += max(0LL, bestReturn[v]);\n            }\n        }\n        bestReturn[u] = compW[u] + sumReturn;\n        long long bestDelta = 0;\n        for(int v : tadj[u]){\n            if(par[v] == u){\n                long long delta = bestNoReturn[v] - max(0LL, bestReturn[v]);\n                if(delta > bestDelta) bestDelta = delta;\n            }\n        }\n        bestNoReturn[u] = compW[u] + sumReturn + max(0LL, bestDelta);\n    }\n\n    cout << bestNoReturn[root] << \"\\n\";\n    return 0;\n}\nCPP\n\ng++ -std=c++17 -O2 -pipe -static -s -o main main.cpp\n\n./main << EOF\n5 7\n2 2 8 6 9\n1 2\n1 3\n2 4\n3 2\n4 5\n2 5\n1 5\n2\nEOF",
