#include <bits/stdc++.h>
using namespace std;

// Brute force verifier for small A,B.
// For all s,t in [1, A+B], recursively simulate removals with choices among
// first, s-th (if exists), and t-th (if exists). Collect all color sequences.

unordered_set<string> all_sequences;

void dfs(int r, int b, int s, int t, string &seq){
    int L = r + b;
    if(L == 0){
        all_sequences.insert(seq);
        return;
    }
    // Option 1: remove first ball
    if(L >= 1){
        if(r > 0){ seq.push_back('R'); dfs(r-1, b, s, t, seq); seq.pop_back(); }
        else { seq.push_back('B'); dfs(r, b-1, s, t, seq); seq.pop_back(); }
    }
    // Option 2: remove s-th ball (if exists)
    if(s <= L){
        if(s <= r){ seq.push_back('R'); dfs(r-1, b, s, t, seq); seq.pop_back(); }
        else { seq.push_back('B'); dfs(r, b-1, s, t, seq); seq.pop_back(); }
    }
    // Option 3: remove t-th ball (if exists)
    if(t <= L){
        if(t <= r){ seq.push_back('R'); dfs(r-1, b, s, t, seq); seq.pop_back(); }
        else { seq.push_back('B'); dfs(r, b-1, s, t, seq); seq.pop_back(); }
    }
}

int count_sequences(int A, int B){
    all_sequences.clear();
    string seq;
    int N = A + B;
    for(int s = 1; s <= N; ++s){
        for(int t = 1; t <= N; ++t){
            // reset and explore for fixed s,t
            string local_seq;
            // Use a local set to collect sequences for this (s,t) if desired
            // but we can merge directly into global all_sequences via dfs
            dfs(A, B, s, t, local_seq);
        }
    }
    return (int)all_sequences.size();
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int A,B;
    if(!(cin>>A>>B)) return 0;
    int ans = count_sequences(A,B);
    cout << ans << "\n";
    return 0;
}
