      "keystrokes": "bash -lc 'cat > main.cpp << '\\''CPP'\n#include <bits/stdc++.h>\nusing namespace std;\nstatic int N; // number of rows\n\nstruct Node {\n  bool empty;\n  int ans;\n  int k; // number of boundary components\n  int left_vals[12];\n  int right_vals[12];\n  int Lids[12];\n  int Rids[12];\n  Node(): empty(true), ans(0), k(0) {}\n};\n\nstruct DSU {\n  vector<int> p, r;\n  DSU(int n=0){ init(n); }\n  void init(int n){ p.resize(n); r.assign(n,0); iota(p.begin(), p.end(), 0); }\n  int find(int x){ return p[x]==x ? x : p[x] = find(p[x]); }\n  bool unite(int a, int b){ int ra=find(a), rb=find(b); if(ra==rb) return false; if(r[ra] < r[rb]) swap(ra, rb); p[rb] = ra; if(r[ra]==r[rb]) r[ra]++; return true; }\n};\n\n// forward declare to use N\n\nNode mergeNodes(const Node& A, const Node& B){\n  if(A.empty) return B;\n  if(B.empty) return A;\n  Node C; C.empty = false;\n  C.ans = A.ans + B.ans;\n  for(int i=0;i<N;i++){ C.left_vals[i] = A.left_vals[i]; C.right_vals[i] = B.right_vals[i]; }\n  int kA = A.k, kB = B.k;\n  DSU dsu(kA + kB);\n  for(int i=0;i<N;i++){\n    if(A.right_vals[i] == B.left_vals[i]){\n      if(dsu.unite(A.Rids[i], kA + B.Lids[i])) C.ans--;\n    }\n  }\n  unordered_map<int,int> mp; mp.reserve(2*N);\n  int next_id = 0;\n  auto getId = [&](int root)->int {\n    auto it = mp.find(root);\n    if(it == mp.end()){ mp[root] = next_id; return next_id++; }\n    return it->second;\n  };\n  // Left boundary of the merged segment\n  for(int i=0;i<N;i++){\n    int root = dsu.find(A.Lids[i]);\n    C.Lids[i] = getId(root);\n  }\n  // Right boundary of the merged segment\n  for(int i=0;i<N;i++){\n    int root = dsu.find(kA + B.Rids[i]);\n    C.Rids[i] = getId(root);\n  }\n  C.k = next_id;\n  return C;\n}\n\nNode buildLeaf(int col, const vector<vector<int>>& mat){\n  Node nd; nd.empty = false;\n  int id = -1;\n  for(int i=0;i<N;i++){\n    nd.left_vals[i] = mat[i][col];\n    nd.right_vals[i] = mat[i][col];\n    if(i==0 || mat[i][col] != mat[i-1][col]) id++;\n    nd.Lids[i] = nd.Rids[i] = id;\n  }\n  nd.ans = id + 1;\n  nd.k = id + 1;\n  return nd;\n}\n\nstruct SegTree {\n  int n;\n  vector<Node> st;\n  const vector<vector<int>>& mat; // n x m\n  SegTree(const vector<vector<int>>& A): mat(A) {\n    n = (int)A[0].size();\n    st.resize(4*n);\n    build(1,0,n-1);\n  }\n  void build(int idx, int l, int r){\n    if(l==r){ st[idx] = buildLeaf(l, mat); }\n    else {\n      int mid=(l+r)/2;\n      build(idx*2, l, mid);\n      build(idx*2+1, mid+1, r);\n      st[idx] = mergeNodes(st[idx*2], st[idx*2+1]);\n    }\n  }\n  Node query(int idx, int l, int r, int ql, int qr){\n    if(ql <= l && r <= qr) return st[idx];\n    int mid=(l+r)/2;\n    if(qr <= mid) return query(idx*2, l, mid, ql, qr);\n    if(ql > mid) return query(idx*2+1, mid+1, r, ql, qr);\n    Node left = query(idx*2, l, mid, ql, qr);\n    Node right = query(idx*2+1, mid+1, r, ql, qr);\n    return mergeNodes(left, right);\n  }\n  Node query(int l, int r){ if(l>r){ Node e; e.empty=true; return e; } return query(1,0,n-1,l,r); }\n};\n\nint main(){\n  ios::sync_with_stdio(false);\n  cin.tie(nullptr);\n  int n, m, q;\n  if(!(cin >> n >> m >> q)) return 0;\n  N = n;\n  vector<vector<int>> a(n, vector<int>(m));\n  for(int i=0;i<n;i++) for(int j=0;j<m;j++) cin >> a[i][j];\n  SegTree st(a);\n  while(q--){ int l,r; cin >> l >> r; l--; r--; Node res = st.query(l, r); cout << res.ans << '\\n'; }\n  return 0;\n}\nCPP'\n",
